    quiz: { prompt: "Pour dire « un peu fatigué » (sens négatif), on dit...", promptEn: "To say \"a little tired\" (negative sense), you say...", choices: ["一点儿累", "有点儿累", "累一点儿", "有累"], correctChoiceIndex: 1 }
