    quiz: { prompt: "« J'ai téléphoné à ma mère » = ?", promptEn: "\"I phoned my mother\" = ?", choices: ["我对妈妈打电话了", "我给妈妈打电话了", "我跟妈妈打电话了", "我和妈妈打电话了"], correctChoiceIndex: 1 }
